/**
 * A platform whose clock a test advances by hand: `after` waits for `advance`, earliest first,
 * and a wait started while advancing ends in the same advance when it falls inside it. `hide` and
 * `show` change what the document reports for `visibilitychange`.
 */
class ManualPlatform {
  private now = 0;
  private started = 0;
  private hidden = false;
  private readonly waiting = new Set<{ at: number; order: number; run: () => void }>();
  private readonly listeners = new Set<(hidden: boolean) => void>();

  monotonicMs(): number {
    return this.now;
  }

  after(milliseconds: number, callback: () => void): Cancel {
    const entry = { at: this.now + milliseconds, order: this.started++, run: callback };
    this.waiting.add(entry);
    return () => {
      this.waiting.delete(entry);
    };
  }

  pageHidden(): boolean {
    return this.hidden;
  }

  whenVisibilityChanges(onChange: (hidden: boolean) => void): Cancel {
    this.listeners.add(onChange);
    return () => {
      this.listeners.delete(onChange);
    };
  }

  /** How many owners still follow the page's visibility. */
  get following(): number {
    return this.listeners.size;
  }

  setHidden(hidden: boolean): void {
    if (hidden !== this.hidden) {
      this.hidden = hidden;
      for (const listener of [...this.listeners]) {
        listener(hidden);
      }
    }
  }

  advance(milliseconds: number): void {
    const until = this.now + milliseconds;
    for (;;) {
      const due = [...this.waiting]
        .filter((entry) => entry.at <= until)
        .sort((a, b) => a.at - b.at || a.order - b.order);
      const entry = due[0];
      if (entry === undefined) {
        break;
      }
      this.waiting.delete(entry);
      this.now = entry.at;
      entry.run();
    }
    this.now = until;
  }
}

function ownerOf(platform: ManualPlatform): { owner: ReturnType<typeof createEnvironmentInjector>; scope: TimerScope } {
  const owner = createEnvironmentInjector(
    [{ provide: BrowserPlatform, useValue: platform }],
    TestBed.inject(EnvironmentInjector),
  );
  return { owner, scope: runInInjectionContext(owner, () => new TimerScope()) };
}

